  readonly season: string | null;
  /** `strType`, e.g. `1st`, `2nd`, `GK` */
  readonly type: string | null;
  /** `strEquipment`: the image */
  readonly image: string | null;
  /** `strUsername`: who uploaded it */
  readonly uploadedBy: string | null;
