/**
 * A stadium, arena or circuit.
 */
export interface Venue extends ApiRecord {
  readonly kind: "Venue";
  /** `idVenue` */
  readonly id: number | null;
  /** `strVenue` */
  readonly name: string | null;
  /** `strVenueAlternate` */
  readonly alternateName: string | null;
  /** `strVenueSponsor` */
  readonly sponsorName: string | null;
  /** `strSport` */
  readonly sport: string | null;
  /** `strLocation` */
  readonly location: string | null;
  /** `strCountry` */
  readonly country: string | null;
  /** `strTimezone`, as text, e.g. `UTC +00:00 Greenwich Mean Time (GMT)` */
  readonly timezone: string | null;
  /** `intCapacity` */
  readonly capacity: number | null;
  /** `intFormedYear` */
  readonly formedYear: number | null;
  /** `strArchitect` */
  readonly architect: string | null;
  /** `strCost`, as text */
  readonly cost: string | null;
  /** `strMap`: either `lat, lon` or an image URL */
  readonly map: string | null;
  /** `strThumb` */
  readonly thumb: string | null;
  /** `strLogo` */
  readonly logo: string | null;
  /** `strFanart1`..`strFanart4` */
  readonly fanart: readonly string[];
  /** `strCreativeCommons`: see [Player.creativeCommons] */
  readonly creativeCommons: boolean | null;
  /** `strDescriptionEN`, ... */
  readonly descriptions: Readonly<Record<string, string>>;
  readonly socials: Socials;
  /** `intLoved` */
  readonly loved: number | null;
  /** `strLocked` */
  readonly isLocked: boolean | null;
  /** `idDupe`: set when this record duplicates another venue */
  readonly duplicateOf: number | null;
  /** The English description. */
  readonly description: string | null;
  /** `map` as [latitude, longitude], when it holds coordinates. */
  readonly coordinates: readonly [number, number] | null;
}

/** Every record type. */
export type AnyRecord = Sport | Country | League | Season | SeasonPoster | Team | Event | Standing | LineupEntry | TimelineEntry | EventStat | TvListing | LiveScore | Player | Honour | FormerTeam | Milestone | Contract | EventResult | PlayerStat | Equipment | Venue;

/** @internal */
export function parseSport(raw: RawRecord): Sport {
  const r = new Rec(raw);
  return Object.freeze({
    kind: "Sport",
    raw,
    id: r.id("idSport"),
    name: r.s("strSport"),
    format: r.s("strFormat"),
    description: r.s("strSportDescription"),
    thumb: r.s("strSportThumb"),
    thumbBlackAndWhite: r.s("strSportThumbBW"),
    icon: r.s("strSportIconGreen"),
  });
}

